use super::{copyin, copyout, writable, now_ns, poll_fd};

pub fn call(a: &[usize]) -> isize {
    if a.len() < 5 {
        return -22;
    }
    if a[3] != 0 {
        return -38;
    }
    let nfds = a[1];
    if nfds > 16 {
        return -22;
    }
    let mut buf = [0u8; 128];
    let duration = if a[2] == 0 {
        None
    } else {
        if a[2].checked_add(16).is_none()
            || copyin(a[2], &mut buf[..16]).is_err()
        {
            return -14;
        }
        let sec = i64::from_le_bytes([
            buf[0], buf[1], buf[2], buf[3],
            buf[4], buf[5], buf[6], buf[7],
        ]);
        let nsec = i64::from_le_bytes([
            buf[8], buf[9], buf[10], buf[11],
            buf[12], buf[13], buf[14], buf[15],
        ]);
        if sec < 0 || nsec < 0 || nsec >= 1_000_000_000 {
            return -22;
        }
        match (sec as u64).checked_mul(1_000_000_000)
            .and_then(|v| v.checked_add(nsec as u64))
        {
            Some(v) => Some(v),
            None => return -22,
        }
    };
    let len = nfds * 8;
    if len != 0 {
        if a[0] == 0
            || a[0].checked_add(len).is_none()
            || copyin(a[0], &mut buf[..len]).is_err()
            || !writable(a[0], len)
        {
            return -14;
        }
    }
    let deadline = match duration {
        Some(v) => match now_ns().checked_add(v) {
            Some(end) => Some(end),
            None => return -22,
        },
        None => None,
    };
    loop {
        let mut ready: isize = 0;
        let mut i = 0;
        while i < nfds {
            let offset = i * 8;
            let fd = i32::from_le_bytes([
                buf[offset], buf[offset + 1],
                buf[offset + 2], buf[offset + 3],
            ]);
            let events = i16::from_le_bytes([
                buf[offset + 4], buf[offset + 5],
            ]);
            let revents = if fd < 0 { 0 } else { poll_fd(fd, events) };
            let bytes = revents.to_le_bytes();
            buf[offset + 6] = bytes[0];
            buf[offset + 7] = bytes[1];
            if revents != 0 {
                ready += 1;
            }
            i += 1;
        }
        let finished = if ready != 0 {
            true
        } else {
            match deadline {
                Some(end) => now_ns() >= end,
                None => false,
            }
        };
        if finished {
            if len != 0 && copyout(a[0], &buf[..len]).is_err() {
                return -14;
            }
            return ready;
        }
    }
}
